    or v_config_sha256<>'69316475e96e470840874a2eeeffa7f4a19319a437e6d947da101c4668267fb7'
    or v_manifest_sha256<>'a1e596f7707c851534e04e30d13f4289439449556787c572736e77b279c75292'
